def search(books, term, page, size):
    if page < 1 or size < 1:
        raise ValueError('page and size must be positive')
    matches = [b for b in books if term.casefold() in b['title'].casefold()]
    total = len(matches)
    pages = (total + size - 1) // size
    start = (page - 1) * size
    items = matches[start:start + size]
    return {'items': items, 'total': total, 'pages': pages}
